/// Conformance tests: contract vectors plus every golden scenario recorded by the oracle.
/// Set MONSTERA_CONFORMANCE_OUT to a file path to also receive one JSON line per checkpoint.
final class ConformanceTests: XCTestCase {
    func testFixedPointVectors() {
        XCTAssertEqual(Fx.mul(-1, 1), -1)
        XCTAssertEqual(Fx.mul(Fx.rawMax, Fx.rawMax), Fx.rawMax)
        XCTAssertEqual(Fx.mul(Fx.rawMin, Fx.rawMin), Fx.rawMax)
        XCTAssertEqual(Fx.mul(-3, 32768), -2)
        XCTAssertEqual(Fx.mul(3, -32768), -2)
        XCTAssertEqual(Fx.div(65536, 196608), 21845)
        XCTAssertEqual(Fx.div(-65536, 196608), -21845)
        XCTAssertEqual(Fx.div(65536, -196608), -21845)
        XCTAssertEqual(Fx.div(5, 0), Fx.rawMax)
        XCTAssertEqual(Fx.div(-5, 0), Fx.rawMin)
        XCTAssertEqual(Fx.div(0, 0), 0)
        XCTAssertEqual(Fx.div(Fx.rawMin, -1), Fx.rawMax)
        XCTAssertEqual(Fx.neg(Fx.rawMin), Fx.rawMax)
        XCTAssertEqual(Fx.add(Fx.rawMax, 1), Fx.rawMax)
        XCTAssertEqual(Fx.sub(Fx.rawMin, 1), Fx.rawMin)
        // Operands outside the raw range are saturated first: no wrap, no trap.
        XCTAssertEqual(Fx.add(Int64.max, 1), Fx.rawMax)
        XCTAssertEqual(Fx.sub(Int64.min, Int64.max), Fx.rawMin)
        XCTAssertEqual(Fx.neg(Int64.min), Fx.rawMax)
        XCTAssertEqual(Fx.mul(Int64.max, Int64.max), Fx.rawMax)
        XCTAssertEqual(Fx.mul(Int64.min, 65536), Fx.rawMin)
        XCTAssertEqual(Fx.div(Int64.max, 1), Fx.rawMax)
        XCTAssertEqual(Fx.div(1, Int64.min), 0)
    }

    func testRandomnessVectors() {
        var ref = Pcg32(initstate: 42, initseq: 54)
        XCTAssertEqual((0..<6).map { _ in ref.nextU32() },
                       [0xa15c02b7, 0x7b47f409, 0xba1d3330, 0x83d2f293, 0xbfa4784b, 0xcbed606e])
        XCTAssertEqual(fnv1a64(Array("foobar".utf8)), 0x85944171f73967e8)
        XCTAssertEqual(fnv1a64(Array("a".utf8)), 0xaf63dc4c8601ec8c)

        var spawn = Pcg32(seed: 12345, stream: "spawn")
        XCTAssertEqual((0..<4).map { _ in spawn.nextU32() }, [3836204951, 2901556457, 1288830458, 20171900])
        XCTAssertEqual(spawn.state, 0xbe81daf6f5b5d3bb)
        XCTAssertEqual(spawn.inc, 0x6f4a8582f6e4629f)

        var fx = Pcg32(seed: 12345, stream: "fx")
        XCTAssertEqual((0..<4).map { _ in fx.nextU32() }, [3544770967, 1588508108, 78643710, 1025764217])

        var bounded = Pcg32(seed: 1, stream: "spawn")
        XCTAssertEqual((0..<8).map { _ in bounded.nextBelow(10) }, [6, 0, 2, 2, 1, 0, 3, 7])
        XCTAssertEqual([bounded.nextBelow(1), bounded.nextBelow(1)], [0, 0])
        XCTAssertEqual(bounded.nextBelow(1 << 31), 1771058001)
    }

    private func clockRun(_ rate: Int, _ max: Int, _ frames: [Int64]) -> ([Int], Int64, Int64) {
        var c = FrameClock(tickRate: rate, maxTicksPerFrame: max)
        let ticks = frames.map { c.advance($0) }
        return (ticks, c.remainder, c.alpha)
    }

    func testFrameClockVectors() {
        func check(_ got: ([Int], Int64, Int64), _ ticks: [Int], _ rem: Int64, _ alpha: Int64, line: UInt = #line) {
            XCTAssertEqual(got.0, ticks, line: line)
            XCTAssertEqual(got.1, rem, line: line)
            XCTAssertEqual(got.2, alpha, line: line)
        }
        check(clockRun(60, 5, Array(repeating: 16666667, count: 4)), [1, 1, 1, 1], 80, 0)
        check(clockRun(60, 5, Array(repeating: 16666666, count: 4)), [0, 1, 1, 1], 999999840, 65535)
        check(clockRun(60, 5, Array(repeating: 8333333, count: 6)), [0, 0, 1, 0, 1, 0], 999999880, 65535)
        check(clockRun(60, 5, [500000000, 16666667]), [5, 1], 20, 0)
        check(clockRun(60, 5, [-5, 0, 2000000000]), [0, 0, 5], 0, 0)
        check(clockRun(60, 5, [8333333]), [0], 499999980, 32767)
        check(clockRun(60, 100, [2000000000]), [60], 0, 0)
        check(clockRun(120, 5, [8333334, 8333333, 8333333]), [1, 1, 1], 0, 0)
        var x: Int64 = 12345
        var frames: [Int64] = []
        for _ in 0..<1000 {
            x = (x * 1103515245 + 12345) & 0x7FFFFFFF
            frames.append(4_000_000 + (x >> 8) % 36_000_000)
        }
        var c = FrameClock(tickRate: 60, maxTicksPerFrame: 5)
        var total = 0
        for f in frames { total += c.advance(f) }
        XCTAssertEqual(total, 490)
        XCTAssertEqual(c.remainder, 103339700)
    }

    private func idleReplayHash(_ seed: UInt64, _ ticks: Int) -> UInt64 {
        replay(config: GeneratedRuntimeConfig.config, seed: seed, ticks: ticks, inputs: [], checkpointTicks: [ticks])[0].hash
    }

    private func newLoop(_ seed: UInt64, maxTicks: Int = GeneratedRuntimeConfig.maxTicksPerFrame) -> GameLoop {
        GameLoop(world: World(config: GeneratedRuntimeConfig.config, seed: seed),
                 tickRate: GeneratedRuntimeConfig.tickRate, maxTicksPerFrame: maxTicks)
    }

    func testIdleStateIsIndependentOfDisplayRateAndJitter() {
        for hz in [30, 60, 90, 120, 144] {
            var loop = newLoop(7)
            var x = Int64(hz)
            for i in 0..<400 {
                x = (x * 1103515245 + 12345) & 0x7FFFFFFF
                loop.frame(elapsedNanos: 1_000_000_000 / Int64(hz) + (x >> 8) % 2_000_000 - 1_000_000)
                if i % 40 == 0 {
                    XCTAssertEqual(loop.world.stateHash(), idleReplayHash(7, Int(loop.world.tick)), "hz=\(hz) frame=\(i)")
                }
            }
        }
    }

    func testInputsApplyAtTheStartOfTheNextTickInOrder() {
        var loop = newLoop(9)
        var recorded: [TickInput] = []
        var x: Int64 = 3
        for i in 0..<600 {
            var events: [InputEvent] = []
            if i % 7 == 0 { events.append(InputEvent(.tap)) }
            if i % 11 == 0 { events.append(InputEvent(.drag, dx: Int64((i % 13) - 6) * 65536, dy: 0)) }
            for ev in events {
                loop.submit(ev)
                recorded.append(TickInput(tick: Int(loop.world.tick), events: [ev]))
            }
            x = (x * 1103515245 + 12345) & 0x7FFFFFFF
            loop.frame(elapsedNanos: 10_000_000 + (x >> 8) % 25_000_000)
        }
        let ticks = Int(loop.world.tick)
        // Some specs end early (lives run out); a finished world is a no-op in both loop and replay.
        XCTAssertGreaterThan(ticks, 10)
        let want = replay(config: GeneratedRuntimeConfig.config, seed: 9, ticks: ticks, inputs: recorded,
                          checkpointTicks: [ticks])[0].hash
        XCTAssertEqual(loop.world.stateHash(), want)
    }

    func testHitchIsCappedAndBacklogDropped() {
        let cap = GeneratedRuntimeConfig.maxTicksPerFrame
        var loop = newLoop(1, maxTicks: cap)
        XCTAssertEqual(loop.frame(elapsedNanos: 2_000_000_000), cap)
        XCTAssertEqual(loop.frame(elapsedNanos: 1_000_000), 0)
    }

    private struct Scenario {
        let name: String
        let seed: UInt64
        let ticks: Int
        var frames: FrameSpec?
        var inputs: [TickInput] = []
        var expected: [Checkpoint] = []
    }

    private func parseScenarios() throws -> [Scenario] {
        guard let url = Bundle.module.url(forResource: "monstera-scenarios", withExtension: "txt") else {
            XCTFail("monstera-scenarios.txt is missing from the test resources")
            return []
        }
        let text = try String(contentsOf: url, encoding: .utf8)
        var out: [Scenario] = []
        var current: Scenario?
        for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
            if line.hasPrefix("#") || line.hasPrefix("monstera-scenarios ") { continue }
            let p = line.split(separator: " ").map(String.init)
            switch p[0] {
            case "scenario":
                current = Scenario(name: p[1], seed: UInt64(p[2])!, ticks: Int(p[3])!)
            case "frames":
                current!.frames = FrameSpec(count: Int(p[1])!, seed: Int64(p[2])!, minNanos: Int64(p[3])!, maxNanos: Int64(p[4])!)
            case "input":
                let types: [String: InputType] = ["press": .press, "release": .release, "tap": .tap, "drag": .drag, "swipe": .swipe]
                let dirs: [String: Direction] = ["none": .none, "up": .up, "down": .down, "left": .left, "right": .right]
                let event = InputEvent(types[p[2]]!, dx: Int64(p[3])!, dy: Int64(p[4])!, dir: dirs[p[5]]!)
                let tick = Int(p[1])!
                if let last = current!.inputs.last, last.tick == tick {
                    current!.inputs[current!.inputs.count - 1] = TickInput(tick: tick, events: last.events + [event])
                } else {
                    current!.inputs.append(TickInput(tick: tick, events: [event]))
                }
            case "checkpoint":
                current!.expected.append(Checkpoint(tick: Int(p[1])!, hash: UInt64(p[2], radix: 16)!,
                                                    observe: p[3...8].map { Int64($0)! }))
            case "end":
                out.append(current!)
                current = nil
            default:
                XCTFail("unknown line: \(line)")
            }
        }
        return out
    }

    private func hex(_ h: UInt64) -> String {
        let s = String(h, radix: 16)
        return String(repeating: "0", count: 16 - s.count) + s
    }

    func testGoldenScenarios() throws {
        let scenarios = try parseScenarios()
        XCTAssertFalse(scenarios.isEmpty, "no scenarios found")
        var lines: [String] = []
        var failures: [String] = []
        for sc in scenarios {
            let checkpointTicks = sc.expected.map { $0.tick }
            let got: [Checkpoint]
            if let spec = sc.frames {
                got = replayFrames(config: GeneratedRuntimeConfig.config, seed: sc.seed, tickRate: GeneratedRuntimeConfig.tickRate,
                                   maxTicksPerFrame: GeneratedRuntimeConfig.maxTicksPerFrame, frames: spec,
                                   inputs: sc.inputs, checkpointFrames: checkpointTicks)
            } else {
                got = replay(config: GeneratedRuntimeConfig.config, seed: sc.seed, ticks: sc.ticks,
                             inputs: sc.inputs, checkpointTicks: checkpointTicks)
            }
            for g in got {
                lines.append("{\"platform\":\"swift\",\"scenario\":\"\(sc.name)\",\"tick\":\(g.tick),\"hash\":\"\(hex(g.hash))\","
                             + "\"observe\":[\(g.observe.map { String($0) }.joined(separator: ","))]}")
            }
            if let bad = zip(sc.expected, got).first(where: { $0 != $1 }) {
                let fields = observableNames.indices.filter { bad.0.observe[$0] != bad.1.observe[$0] }
                    .map { observableNames[$0] }.joined(separator: ", ")
                failures.append("\(sc.name): first divergence at tick \(bad.0.tick) (hash \(hex(bad.0.hash)) vs \(hex(bad.1.hash)); fields: \(fields.isEmpty ? "hash only" : fields))")
            } else if got.count != sc.expected.count {
                failures.append("\(sc.name): produced \(got.count) checkpoints, expected \(sc.expected.count)")
            }
        }
        if let path = ProcessInfo.processInfo.environment["MONSTERA_CONFORMANCE_OUT"] {
            try (lines.joined(separator: "\n") + "\n").write(toFile: path, atomically: true, encoding: .utf8)
        }
        XCTAssertTrue(failures.isEmpty, failures.joined(separator: "\n"))
    }
